/**
 * Result of validating a Spectral ruleset.
 */
export type SpectralRulesetValidationResult =
  | { isValid: true }
  | { isValid: false; error: string };

/**
 * Normalizes a value to an array:
 *  - `undefined` becomes `[]`
 *  - a non-array value is wrapped in a single-element array
 *  - an array is returned unchanged
 */
export function toArray<T>(value: T | T[] | undefined): T[] {
  if (value === undefined) {
    return [];
  }
  return Array.isArray(value) ? value : [value];
}

// Top-level keys we allow in a ruleset. Notably `functions` is NOT allowed as
// it is used to declare custom JavaScript functions, which we never execute.
const ALLOWED_TOP_LEVEL_KEYS = new Set([
  'extends',
  'rules',
  'documentationUrl',
  'formats',
  'aliases',
  'overrides',
  'parserOptions',
]);

// Built-in Spectral functions. A rule's `then.function` must reference one of
// these - custom functions are not permitted.
const BUILTIN_FUNCTIONS = new Set([
  'alphabetical',
  'casing',
  'defined',
  'enumeration',
  'falsy',
  'length',
  'pattern',
  'schema',
  'truthy',
  'typedEnum',
  'undefined',
  'unreferencedReusableObject',
  'or',
  'xor',
]);

// Valid severity strings that a rule shorthand may use.
const VALID_SEVERITIES = new Set(['error', 'warn', 'info', 'hint', 'off']);

// Tokens that could be used for prototype pollution.
const PROTOTYPE_POLLUTING_TOKENS = ['__proto__', 'prototype', 'constructor'];

const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  value !== null && typeof value === 'object' && !Array.isArray(value);

const containsPrototypePollutingToken = (value: string): boolean =>
  PROTOTYPE_POLLUTING_TOKENS.some(token => value.includes(token));

/**
 * Validates the content of a Spectral ruleset file without executing any of
 * it. This is a defensive, allow-list based validation intended to reject
 * rulesets that could be used to run arbitrary code or pollute prototypes.
 */
export function validateSpectralRuleset(content: string): SpectralRulesetValidationResult {
  if (!content || content.trim() === '') {
    return { isValid: false, error: 'Ruleset is empty.' };
  }

  let parsed: unknown;
  try {
    parsed = parse(content);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return { isValid: false, error: `Ruleset could not be parsed as YAML or JSON: ${message}` };
  }

  if (!isPlainObject(parsed)) {
    return { isValid: false, error: 'Ruleset must be an object at the top level.' };
  }

  const keys = Object.keys(parsed);
  if (keys.length === 0) {
    return { isValid: false, error: 'Ruleset must declare at least one of "extends" or "rules".' };
  }

  for (const key of keys) {
    if (!ALLOWED_TOP_LEVEL_KEYS.has(key)) {
      return { isValid: false, error: `Unsupported top-level key "${key}" in ruleset.` };
    }
  }

  // extends
  if ('extends' in parsed) {
    const extendsEntries = toArray(parsed.extends as unknown);
    for (const entry of extendsEntries) {
      if (typeof entry !== 'string') {
        return { isValid: false, error: '"extends" entries must be strings.' };
      }
    }
  }

  // rules
  if ('rules' in parsed) {
    const rules = parsed.rules;
    if (!isPlainObject(rules)) {
      return { isValid: false, error: '"rules" must be an object.' };
    }

    for (const ruleName of Object.keys(rules)) {
      const ruleBody = rules[ruleName];

      // Rule shorthands: a boolean or a severity string.
      if (typeof ruleBody === 'boolean') {
        continue;
      }
      if (typeof ruleBody === 'string') {
        if (!VALID_SEVERITIES.has(ruleBody)) {
          return {
            isValid: false,
            error: `Rule "${ruleName}" must be an object, boolean, or severity string.`,
          };
        }
        continue;
      }

      if (!isPlainObject(ruleBody)) {
        return {
          isValid: false,
          error: `Rule "${ruleName}" must be an object, boolean, or severity string.`,
        };
      }

      // A rule whose body is an object must not use a prototype-polluting name.
      if (PROTOTYPE_POLLUTING_TOKENS.includes(ruleName)) {
        return { isValid: false, error: `Rule name "${ruleName}" is not allowed.` };
      }

      const ruleError = validateRuleObject(ruleName, ruleBody);
      if (ruleError) {
        return { isValid: false, error: ruleError };
      }
    }
