  if ('documentationUrl' in parsed) {
    const documentationUrl = parsed.documentationUrl;
    if (typeof documentationUrl === 'string') {
      let usesHttps = false;
      try {
        usesHttps = new URL(documentationUrl).protocol === 'https:';
      } catch {
        usesHttps = false;
      }
      if (!usesHttps) {
        return { isValid: false, error: 'documentationUrl must use the https scheme.' };
      }
    }
  }

  return { isValid: true };
}

/**
 * Validates the interesting fields of a single rule object (`given` and
 * `then`). Returns an error string, or `undefined` if the rule is valid.
 */
function validateRuleObject(ruleName: string, rule: Record<string, unknown>): string | undefined {
  // given: a JSONPath expression (or array of them). Reject any that contain
  // prototype-polluting tokens. Non-string entries are skipped.
  if ('given' in rule) {
    for (const given of toArray(rule.given as unknown)) {
      if (typeof given !== 'string') {
        continue;
      }
      if (containsPrototypePollutingToken(given)) {
        return `Rule "${ruleName}" "given" contains a disallowed token.`;
      }
    }
  }

  // then: a single object or an array of objects. Non-object entries in an
  // array are skipped.
  if ('then' in rule) {
    for (const then of toArray(rule.then as unknown)) {
      if (!isPlainObject(then)) {
        continue;
      }

      // then.field must be a plain property name - no prototype-polluting
      // tokens and no path-traversal characters.
      if ('field' in then && typeof then.field === 'string') {
        const field = then.field;
        if (containsPrototypePollutingToken(field) || /[.[\]]/.test(field)) {
          return `Rule "${ruleName}" "then.field" is not a valid field name.`;
        }
      }

      // then.function must reference a built-in function.
      if ('function' in then) {
        const fn = then.function;
        if (typeof fn !== 'string' || !BUILTIN_FUNCTIONS.has(fn)) {
          return `Rule "${ruleName}" "then.function" is not an allowed built-in function.`;
        }
      }
    }
  }

  return undefined;
}
